package io.github.diodeme.ji.ai;

import java.util.List;
import java.util.Map;

/** Complete immutable input to one model attempt. */
public record ModelRequest(
        String sessionId,
        ModelRef model,
        String systemPrompt,
        List<Message> messages,
        List<ToolSchema> tools,
        Map<String, Object> options,
        CancellationToken cancellation) {
    public ModelRequest {
        if (sessionId == null || sessionId.isBlank()) throw new IllegalArgumentException("sessionId must not be blank");
        if (model == null) throw new IllegalArgumentException("model must not be null");
        if (systemPrompt == null) throw new IllegalArgumentException("systemPrompt must not be null");
        messages = List.copyOf(messages);
        tools = List.copyOf(tools);
        options = Map.copyOf(options);
        if (cancellation == null) throw new IllegalArgumentException("cancellation must not be null");
    }
}
